package com.owuor.educue.graduation.service;
import com.owuor.educue.finance.repository.FeeLedgerRepository; import com.owuor.educue.graduation.enums.*; import com.owuor.educue.graduation.repository.*; import com.owuor.educue.students.enums.EnrollmentStatus; import com.owuor.educue.students.repository.EnrollmentRepository; import com.owuor.educue.users.repository.UserRepository;
import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*; import java.math.BigDecimal; import java.time.*;
@Service @RequiredArgsConstructor
public class GraduationCandidateProcessor {private final GraduationBatchCandidateRepository candidateRepository;private final GraduationApplicationRepository applicationRepository;private final EnrollmentRepository enrollmentRepository;private final FeeLedgerRepository ledgerRepository;private final UserRepository userRepository;
 @Transactional(propagation=Propagation.REQUIRES_NEW) public void process(Long candidateId,Long userId){var c=candidateRepository.findById(candidateId).orElseThrow();try{var a=c.getApplication();var e=a.getEnrollment();String reason=null;if(a.getStatus()!=GraduationApplicationStatus.APPROVED_FOR_GRADUATION)reason="Candidate is not on the final graduation list";else if(!Boolean.TRUE.equals(a.getClearanceComplete()))reason="Clearance is incomplete";else if(ledgerRepository.getOutstandingBalance(e.getStudent().getId()).compareTo(BigDecimal.ZERO)>0)reason="Student has an outstanding school balance";else if(e.getStatus()!=EnrollmentStatus.ACTIVE)reason="Enrollment is not active";if(reason!=null){c.setStatus(GraduationBatchCandidateStatus.SKIPPED);c.setFailureReason(reason);}else{var user=userRepository.getReferenceById(userId);e.setStatus(EnrollmentStatus.GRADUATED);enrollmentRepository.save(e);a.setStatus(GraduationApplicationStatus.GRADUATED);a.setGraduationBatch(c.getBatch());a.setGraduationDate(c.getBatch().getGraduationDate());a.setConferredBy(user);a.setConferredAt(LocalDateTime.now());applicationRepository.save(a);c.setStatus(GraduationBatchCandidateStatus.GRADUATED);}c.setProcessedAt(LocalDateTime.now());candidateRepository.save(c);}catch(Exception ex){c.setStatus(GraduationBatchCandidateStatus.FAILED);c.setFailureReason(ex.getMessage()==null?"Unexpected processing error":ex.getMessage().substring(0,Math.min(500,ex.getMessage().length())));c.setProcessedAt(LocalDateTime.now());candidateRepository.save(c);}}
}
